// spec: specs/premium-store.md (раздел 3.2)
// seed: tests/seed.free.spec.ts
import { test, expect } from '@playwright/test';
import path from 'path';

test.use({ storageState: path.resolve(__dirname, '../../../auth/free-r13.json'), colorScheme: 'dark' });

test.describe('Раунд 13: «בוסטים» и «סופר לייק» (#4ef651)', () => {
  test('/super-likes: пакеты 3/15/30, цены, плашка Premium @iphone @prod-safe', async ({ page }) => {
    const purchaseRequests: string[] = [];
    page.on('request', (r) => {
      if (/purchase|payment|checkout/i.test(r.url())) purchaseRequests.push(r.url());
    });

    // 1. `/super-likes`; посмотреть экран до низа.
    await page.goto('/super-likes');
    await expect(page.getByText('סופר לייק', { exact: true }).first()).toBeVisible();

    const p3 = page.getByRole('radio', { name: /^3 סופר לייק ₪19\.90 ₪6\.63 ליחידה/ });
    const p15 = page.getByRole('radio', { name: /15 סופר לייק ₪39\.90 ₪2\.66 ליחידה/ });
    const p30 = page.getByRole('radio', { name: /30 סופר לייק ₪59\.90 ₪1\.99 ליחידה/ });
    await expect(p3).toBeVisible();
    await expect(p15).toBeVisible();
    await expect(p30).toBeVisible();
    await expect(p15).toContainText('פופולרי');
    await expect(p15).toContainText('-60%');
    await expect(p30).toContainText('-70%');

    await expect(page.getByText(/^יש לך$/)).toBeVisible();
    await expect(page.getByText(/^\d+ סופר לייק$/)).toBeVisible();
    await expect(page.getByText('איך זה עובד', { exact: true })).toBeVisible();
    await expect(page.getByText('בוחרים פרופיל שמעניין אותך')).toBeVisible();
    await expect(page.getByText('שולחים סופר לייק במקום לייק רגיל')).toBeVisible();
    await expect(page.getByText('העניין שלך מוצג בצורה בולטת')).toBeVisible();
    await expect(page.getByRole('button', { name: 'לקנות 15 סופר לייק · ₪39.90' })).toBeVisible();
    await expect(page.getByText('ב-Premium מקבלים 50 סופר לייק בחודש')).toBeVisible();
    expect(purchaseRequests, 'запросов покупки нет').toEqual([]);
  });
});
